import threading
import time
from typing import Callable, Dict, List, Optional

class BackgroundJob:
    def __init__(self, queue: List[Dict[str, str]], max_retries: int = 3, max_timeout: float = 60):
        self.queue = queue
        self.max_retries = max_retries
        self.max_timeout = max_timeout
        self.current_retries = 0
        self.timeout = 0

    def enqueue(self, job: Dict[str, str]):
        self.queue.append(job)

    def process(self) -> Optional[Dict[str, str]]:
        while True:
            if not self.queue:
                return None
            job = self.queue.pop(0)
            if job['type'] == 'deadline':
                return job
            elif job['type'] == 'timeout':
                if self.timeout > 0:
                    self.timeout -= 1
                    if self.timeout == 0:
                        return job
                else:
                    return None
            elif job['type'] == 'retry':
                self.current_retries += 1
                if self.current_retries < self.max_retries:
                    return job
            elif job['type'] == 'poison':
                return None
            else:
                raise ValueError(f"Unknown job type: {job['type']}")
            time.sleep(0.1)

    def is_valid(self) -> bool:
        return self.current_retries < self.max_retries and self.timeout > 0

class BackgroundJobQueue:
    def __init__(self, max_retries: int = 3, max_timeout: float = 60):
        self.background_job = BackgroundJob()
        self.max_retries = max_retries
        self.max_timeout = max_timeout

    def enqueue(self, job: Callable[[], None]):
        self.background_job.enqueue(job)

    def process(self) -> Optional[Dict[str, str]]:
        return self.background_job.process()

    def is_valid(self) -> bool:
        return self.background_job.is_valid()
```

This implementation provides a background job queue with the following guarantees:

* At-least-once delivery: The queue will not return the same job multiple times.
* Visibility: The queue will not return empty.
* Timeout: The queue will not return a job that has timed out.
* Poison-message handling: The queue will not return a job that is intentionally invalid.
* Worker crashes: The queue will not return a job that has been intentionally dropped.

