class Quotas:
    def __init__(self, cpu, storage):
        self.cpu = cpu
        self.storage = storage
        self.reservations = {}

    def reserve(self, amount):
        if amount > self.cpu:
            raise ValueError("Insufficient CPU")
        if amount > self.storage:
            raise ValueError("Insufficient storage")
        if amount in self.reservations:
            raise ValueError("Reservation already exists")
        self.reservations[amount] = True
        return amount

    def release(self, amount):
        if amount > self.cpu:
            raise ValueError("Insufficient CPU")
        if amount > self.storage:
            raise ValueError("Insufficient storage")
        if amount not in self.reservations:
            raise ValueError("No reservation exists")
        del self.reservations[amount]
        return amount

    def get_remaining(self, amount):
        if amount > self.cpu:
            raise ValueError("Insufficient CPU")
        if amount > self.storage:
            raise ValueError("Insufficient storage")
        return self.cpu - amount

    def get_available(self):
        return self.cpu - sum(self.reservations.values())

