    def __init__(self, max_outbox_size: int = 1000):
        self.outbox = []
        self.lock = threading.Lock()
        self.max_outbox_size = max_outbox_size

    def publish(self, event: Event):
        with self.lock:
            if len(self.outbox) >= self.max_outbox_size:
                raise ValueError("Event cannot be published in this outbox")
            self.outbox.append(event)

    def commit(self):
        with self.lock:
            if not self.outbox:
                return
            for event in self.outbox:
                # Ensure the event is not duplicated
                if not self._has_duplicate(event):
                    self._publish(event)
            self.outbox.clear()

    def _has_duplicate(self, event: Event):
        for existing_event in self.outbox:
            if existing_event.id == event.id and existing_event.type == event.type and existing_event.payload == event.payload:
                return True
